        "titolo_orig": "Luis Puenzo, tra la storia ufficiale e quella personale",
        "testo_it": "Addio al regista argentino Luis Puenzo, vincitore del primo Oscar per l'Argentina.",
        "priorita": "Bassa",
        "id_gruppo": 0,
